create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,display_name text,role text not null default 'reader' check(role in ('reader','admin')),created_at timestamptz default now());
create table if not exists public.books(id uuid primary key default gen_random_uuid(),title text not null,author text,genres text[] not null default '{}',description text,cover_url text,status text not null default 'ongoing',is_published boolean not null default false,created_by uuid references auth.users(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.chapters(id uuid primary key default gen_random_uuid(),book_id uuid not null references public.books(id) on delete cascade,chapter_number integer not null check(chapter_number>0),title text,content text not null default '',is_published boolean not null default false,created_by uuid references auth.users(id),created_at timestamptz default now(),unique(book_id,chapter_number));
create table if not exists public.favorites(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,book_id uuid not null references public.books(id) on delete cascade,created_at timestamptz default now(),unique(user_id,book_id));
create table if not exists public.reading_progress(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,book_id uuid not null references public.books(id) on delete cascade,chapter_id uuid references public.chapters(id) on delete set null,updated_at timestamptz default now(),unique(user_id,book_id));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,display_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'display_name','')) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
alter table public.profiles enable row level security; alter table public.books enable row level security; alter table public.chapters enable row level security; alter table public.favorites enable row level security; alter table public.reading_progress enable row level security;
create policy "profile own read" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "profile own update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid() and role='reader');
create policy "published books read" on public.books for select to anon,authenticated using(is_published or public.is_admin());
create policy "admin books all" on public.books for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "published chapters read" on public.chapters for select to anon,authenticated using(is_published or public.is_admin());
create policy "admin chapters all" on public.chapters for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "own favorites" on public.favorites for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own progress" on public.reading_progress for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
grant usage on schema public to anon,authenticated;
grant select on public.books,public.chapters to anon,authenticated;
grant all on public.books,public.chapters to authenticated;
grant select,update on public.profiles to authenticated;
grant select,insert,delete on public.favorites to authenticated;
grant select,insert,update,delete on public.reading_progress to authenticated;
-- Sau khi đăng ký tài khoản, chạy: update public.profiles set role='admin' where email='EMAIL_DANG_KY_CUA_BAN';
